import torch, time, b200probe
src=r'''
extern "C" __global__ void clk(unsigned long long* out, long long spin_ns){
  unsigned long long t0,t1; asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t0));
  long long c0=clock64();
  do { asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t1)); } while ((long long)(t1-t0) < spin_ns);
  long long c1=clock64(); out[0]=c1-c0; out[1]=t1-t0; }'''
k=b200probe.cuda_kernel(src,'clk'); out=torch.zeros(2,dtype=torch.int64,device='cuda')
torch.backends.cuda.matmul.allow_tf32=True
PPC=1190e12/1.965e9
def sus(fn, flop, secs=0.8):
    for _ in range(3): fn()
    torch.cuda.synchronize(); t0=time.time(); res=[]
    while time.time()-t0<secs:
        s=torch.cuda.Event(enable_timing=True); e=torch.cuda.Event(enable_timing=True); s.record()
        for _ in range(10): fn()
        e.record(); k((1,),(1,),out,20000); torch.cuda.synchronize(); o=out.tolist()
        res.append((s.elapsed_time(e)/10*1e3, o[0]/o[1]*1e3))
    res=res[len(res)//2:]; us=sum(r[0] for r in res)/len(res); f=sum(r[1] for r in res)/len(res)
    tf=flop/us/1e6; return us,tf,f,tf*1e12/(PPC*f*1e6)
cases=[(18432,919,3072),(18432,960,3072),(18432,1024,3072),(18432,512,3072),(18432,691,3072),(18432,2048,3072),(18432,4096,3072),(18432,1024,8192),(6144,1024,3072),(6144,4096,3072),(8192,8192,3072),(8192,8192,8192)]
for (Mw,Nb,K) in cases:
    W=torch.randn(Mw,K,device='cuda'); x=torch.randn(Nb,K,device='cuda')
    us,tf,f,eff=sus(lambda: x@W.t(), 2*Mw*Nb*K)
    print(f"W{Mw} B{Nb} K{K}: {us:.1f} us {tf:.0f} TF/s @ {f:.0f} MHz eff/clk {eff:.3f}")
    del W,x

