#include "cutlass/epilogue/collective/collective_builder.hpp"
#include "cutlass/util/packed_stride.hpp"
namespace adamod {
using namespace cute;
constexpr int kD = 3072; constexpr int kN = 6 * kD;
template <class Base> struct HeldParams { typename Base::Params held; };
template <class Base>
class ChunkedEpilogue : private HeldParams<Base>, public Base {
  using Holder = HeldParams<Base>;
 public:
  struct Arguments { typename Base::Arguments base; float* outs[6]; };
  struct Params { typename Base::Params base; float* outs[6]; };
  template <class PS> static constexpr Params to_underlying_arguments(PS const& ps, Arguments const& a, void* ws) {
    Params p{Base::to_underlying_arguments(ps, a.base, ws), {}}; for (int i = 0; i < 6; ++i) p.outs[i] = a.outs[i]; return p; }
  template <class PS> static size_t get_workspace_size(PS const& ps, Arguments const& a) { return Base::get_workspace_size(ps, a.base); }
  template <class PS> static cutlass::Status initialize_workspace(PS const& ps, Arguments const& a, void* ws, cudaStream_t s, cutlass::CudaHostAdapter* h = nullptr) { return Base::initialize_workspace(ps, a.base, ws, s, h); }
  template <class PS> static bool can_implement(PS const& ps, Arguments const& a) { return Base::can_implement(ps, a.base); }
  CUTLASS_DEVICE static void prefetch_tma_descriptors(Params const&) {}
  CUTLASS_DEVICE ChunkedEpilogue(Params const& p, typename Base::TensorStorage& st) : Holder{p.base}, Base(Holder::held, st), outs_(p.outs) {}
  template <bool ReuseTmem = false, class LP, class LPS, class SP, class SPS, class AP, class APS, class PS, class CS, class CC, class TS, class TM, class Acc, class ST>
  CUTLASS_DEVICE auto store(LP lp, LPS lps, SP sp, SPS sps, AP ap, APS aps, PS ps, CS cs, CC cc, TS ts, TM tm, Acc acc, ST& st) {
    const int c = (int(get<0>(cc)) * int(size<0>(cs))) / kD;
    Holder::held.ptr_D = outs_[c] - (size_t)c * kD;
    return Base::template store<ReuseTmem>(lp, lps, sp, sps, ap, aps, ps, cs, cc, ts, tm, acc, st); }
 private:
  float* const* outs_;
};
template <int TM, int TN, int CN, int TK>
struct Tf32Gemm {
  using MmaTile = Shape<Int<TM>, Int<TN>, Int<TK>>;
  using Cluster = Shape<_2, Int<CN>, _1>;
  using EpiBase = typename cutlass::epilogue::collective::CollectiveBuilder<
      cutlass::arch::Sm100, cutlass::arch::OpClassTensorOp, MmaTile, Cluster,
      cutlass::epilogue::collective::EpilogueTileAuto, float, float, float, cutlass::layout::ColumnMajor, 4, float,
      cutlass::layout::ColumnMajor, 4, cutlass::epilogue::NoSmemWarpSpecialized2Sm,
      cutlass::epilogue::fusion::LinearCombination<float, float, float, float>>::CollectiveOp;
  using Epi = ChunkedEpilogue<EpiBase>;
  using StageSpec = cutlass::gemm::collective::StageCountAutoCarveout<static_cast<int>(sizeof(typename EpiBase::SharedStorage))>;
  using Mainloop = typename cutlass::gemm::collective::CollectiveBuilder<
      cutlass::arch::Sm100, cutlass::arch::OpClassTensorOp, cutlass::tfloat32_t, cutlass::layout::RowMajor, 4,
      cutlass::tfloat32_t, cutlass::layout::ColumnMajor, 4, float, MmaTile, Cluster, StageSpec,
      cutlass::gemm::KernelTmaWarpSpecialized2SmSm100>::CollectiveOp;
  using Kernel = cutlass::gemm::kernel::GemmUniversal<Shape<int, int, int, int>, Mainloop, Epi, void>;
  using Gemm = cutlass::gemm::device::GemmUniversalAdapter<Kernel>;
};
template <class G>
int run_gemm(const float* emb, const float* W, const float* bias, float* const* outs, int B, int device, int sms, cudaStream_t stream) {
  using Kernel = typename G::Kernel; using Gemm = typename G::Gemm;
  using SA = typename Kernel::StrideA; using SB = typename Kernel::StrideB;
  using SC = typename G::EpiBase::StrideC; using SD = typename G::EpiBase::StrideD;
  typename Gemm::Arguments args;
  args.mode = cutlass::gemm::GemmUniversalMode::kGemm;
  args.problem_shape = {kN, B, kD, 1};
  args.mainloop.ptr_A = reinterpret_cast<const cutlass::tfloat32_t*>(W);
  args.mainloop.dA = cutlass::make_cute_packed_stride(SA{}, make_shape(kN, kD, 1));
  args.mainloop.ptr_B = reinterpret_cast<const cutlass::tfloat32_t*>(emb);
  args.mainloop.dB = cutlass::make_cute_packed_stride(SB{}, make_shape(B, kD, 1));
  args.epilogue.base.thread.alpha = 1.f; args.epilogue.base.thread.beta = 1.f;
  args.epilogue.base.ptr_C = bias; SC dC{}; get<1>(dC) = 0; get<2>(dC) = 0; args.epilogue.base.dC = dC;
  args.epilogue.base.ptr_D = outs[0]; SD dD{}; get<1>(dD) = kD; get<2>(dD) = 0; args.epilogue.base.dD = dD;
  for (int i = 0; i < 6; ++i) args.epilogue.outs[i] = outs[i];
  args.hw_info.device_id = device; args.hw_info.sm_count = sms;
  Gemm gemm;
  if (Gemm::get_workspace_size(args) != 0) return 900;
  cutlass::Status s = gemm.can_implement(args); if (s != cutlass::Status::kSuccess) return 100 + (int)s;
  s = gemm.initialize(args, nullptr, stream); if (s != cutlass::Status::kSuccess) return 200 + (int)s;
  s = gemm.run(stream); if (s != cutlass::Status::kSuccess) return 300 + (int)s;
  return (int)cudaGetLastError();
}
}
