#include <cuda_runtime.h>

// One CUTLASS TF32 launch per call; the tile shape is chosen from B only (rented B200 sweep, r1; confirmed in r2 E3).
// Each variant lives in its own translation unit so the build compiles them in parallel.
extern "C" int adamod_gemm_128x64(const float*, const float*, const float*, float* const*, int, int, int, cudaStream_t);
extern "C" int adamod_gemm_256x64(const float*, const float*, const float*, float* const*, int, int, int, cudaStream_t);
extern "C" int adamod_gemm_256x192(const float*, const float*, const float*, float* const*, int, int, int, cudaStream_t);
extern "C" int adamod_gemm_256x256(const float*, const float*, const float*, float* const*, int, int, int, cudaStream_t);

extern "C" int adamod_launch(const float* emb, const float* weight, const float* bias, float* const* outs, int B,
                             cudaStream_t stream) {
  int device = 0;
  cudaGetDevice(&device);
  static int sms = 0;   // device property, queried once
  if (sms == 0) cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, device);
  if (B <= 64) return adamod_gemm_128x64(emb, weight, bias, outs, B, device, sms, stream);
  if (B <= 128) return adamod_gemm_256x64(emb, weight, bias, outs, B, device, sms, stream);
  if (B <= 192) return adamod_gemm_256x192(emb, weight, bias, outs, B, device, sms, stream);
  if (B <= 256) return adamod_gemm_256x256(emb, weight, bias, outs, B, device, sms, stream);
  if (B <= 384) return adamod_gemm_256x192(emb, weight, bias, outs, B, device, sms, stream);
  if (B <= 512) return adamod_gemm_256x256(emb, weight, bias, outs, B, device, sms, stream);
  return adamod_gemm_256x192(emb, weight, bias, outs, B, device, sms, stream);
}
